// Keep only the calendar rows a human has marked as planned:
// Status == "Planned" (case-insensitive, stray spaces ignored).
// If nothing is planned, this returns zero items and the workflow
// quietly stops — no AI call, no drafts, no email, no noise.
return $input.all().filter(item => {
  const status = String(item.json.Status || '').trim().toLowerCase();
  return status === 'planned';
});

