parameters.jsCode:
// The AI returns one JSON object per topic; turn each into one row
// per platform so every draft can be reviewed, edited and approved
// on its own line in the Draft Queue.
const topics = $("Keep This Week's Planned Topics").all();
const rows = [];
$input.all().forEach((item, i) => {
  const raw = item.json.choices[0].message.content;
  let drafts;
  try {
    drafts = JSON.parse(raw);
  } catch (e) {
    throw new Error('The AI reply was not valid JSON. First 200 characters: ' + raw.slice(0, 200));
  }
  const topic = topics[i] ? (topics[i].json.Topic || '') : '';
  for (const platform of ['linkedin', 'x', 'facebook', 'instagram']) {
    if (drafts[platform]) {
      rows.push({ json: {
        topic: topic,
        platform: platform,
        draft_text: drafts[platform],
        status: 'Pending review'
      }});
    }
  }
});
return rows;

